<script setup lang="ts">
import { computed,onBeforeUnmount,ref } from 'vue'
import ExploreFrame from './ExploreFrame.vue'
import WorldSymbol from './WorldSymbol.vue'
import { useExperience } from './use-experience'
import { finishExperience } from './experience-games'
import { instruments,musicPassed,musicTap } from './music-studio'
import { gameSound } from './game-sound'
const props=defineProps<{storageKey?:string}>()
const {save,feedback,frame,resetOpen,act,undo,requestReset,reset,hint,onStop}=useExperience(props,'rhythm-band')
const round=computed(()=>save.value.round),active=ref<''|'demo'|'follow'|'compose'>(''),current=ref(-1),muted=ref(false)
const sound=gameSound();let animation=0,started=0,last=-1,disposed=false,request=0
const rules=['先听一遍示范，亮起的拍子和声音对应同一件乐器。','点击“跟着演奏”，在拍子亮起时敲下对应乐器，也可以在游戏区用键盘 1 至 4。','切到自由编曲，点亮 8、12 或 16 格节奏，再播放自己的小乐队；节奏自动保存在本机。']
function stop(){request++;cancelAnimationFrame(animation);active.value='';current.value=-1;sound.stop()}
onStop(stop)
async function play(mode:'demo'|'follow'|'compose') {
  stop();const currentRequest=request;muted.value=!(await sound.ready());if(disposed || currentRequest!==request || document.hidden)return
  if(mode==='follow'){round.value.hits=round.value.hits.map(()=>0);round.value.wrongBeats=[]}
  active.value=mode;started=performance.now();last=-1
  function tick(now:number){if(!active.value)return;const beat=60000/round.value.bpm,index=Math.round((now-started)/beat)-1,length=mode==='compose'?round.value.grid[0].length:round.value.pattern.length;current.value=index
    if(index!==last && index>=0 && index<length){last=index;if(mode==='demo')sound.note(round.value.pattern[index]);if(mode==='compose')round.value.grid.forEach((row,instrument)=>{if(row[index])sound.note(instrument)})}
    if(now-started>=(length+.5)*beat){if(mode==='follow'){const missed=round.value.hits.filter((value,index)=>!value && !round.value.wrongBeats?.includes(index)).length;round.value.mistakes+=missed;const passed=musicPassed(round.value);finishExperience(save.value,passed);feedback.value=passed?'你和鼓点合上拍啦！也可以继续自由编曲。':'这次先熟悉节奏。听一遍，放慢速度，再跟着试试。'}stop();return}
    animation=requestAnimationFrame(tick)
  }animation=requestAnimationFrame(tick)
}
async function tap(instrument:number){const elapsed=performance.now()-started,currentRequest=request;muted.value=!(await sound.ready());if(disposed || currentRequest!==request || document.hidden)return;sound.note(instrument);if(active.value!=='follow'){feedback.value='点击“跟着演奏”后，就能跟着亮起的拍子一起敲。';return}const result=act(()=>{const result=musicTap(round.value,instrument,elapsed);return result==='outside'?null:result});feedback.value=result==='hit'?'合上拍了！':result==='wrong'?'再听听这一拍是哪件乐器。':'等拍子亮起，在鼓点附近轻轻敲下。'}
function mode(value:'follow'|'compose'){stop();round.value.mode=value;feedback.value=value==='compose'?'点亮格子，把自己的节奏编出来。':'先听示范，再跟着演奏。'}
function cell(instrument:number,step:number){if(active.value)return;act(()=>{round.value.grid[instrument][step]^=1;round.value.moves++;return true})}
function length(value:number){stop();act(()=>{round.value.grid=round.value.grid.map(row=>Array.from({length:value},(_,index)=>row[index]||0));return true})}
function preset(style:number){stop();act(()=>{const size=round.value.grid[0].length;round.value.grid=Array.from({length:4},(_,instrument)=>Array.from({length:size},(_,step)=>style===0?(instrument===0 && step%4===0 || instrument===1 && step%4===2 ? 1 : 0):style===1?(instrument===0 && step%3===0 || instrument===2 && step%3===2 ? 1 : 0):(instrument===0 && step%4===0 || instrument===3 && step%2===1 ? 1 : 0)));return true});feedback.value='范例已放好，可以改几拍，编成自己的节奏。'}
function keyboard(event:KeyboardEvent){if((event.target as HTMLElement).closest('input,select,textarea'))return;const instrument=Number(event.key)-1;if(instrument>=0 && instrument<4){event.preventDefault();tap(instrument)}}
onBeforeUnmount(()=>{disposed=true;stop();sound.dispose()})
</script>
<template>
  <ExploreFrame v-bind="frame" :progress="`${round.hits.filter(Boolean).length} / ${round.pattern.length} 拍`" :rules="rules" @difficulty="requestReset" @undo="undo" @restart="requestReset()" @reset="reset" @cancel="resetOpen=false" @hint="hint('先用慢一点的速度听示范。大鼓低沉，小鼓沙沙响，木琴和铃铛声音更明亮。')">
    <div class="music-room" tabindex="0" aria-label="乐队键盘控制" @keydown="keyboard">
      <div class="explore-toolbar"><button :class="{selected:round.mode==='follow'}" @click="mode('follow')">跟着鼓点</button><button :class="{selected:round.mode==='compose'}" @click="mode('compose')">自由编曲</button><label>速度 <input v-model.number="round.bpm" :disabled="!!active" type="range" min="48" max="144" aria-label="乐队速度">{{ round.bpm }} 拍/分</label></div>
      <div class="music-banner"><span>♪</span><div><small>小小乐队排练中</small><h2>{{ active==='follow'?'听见鼓点，敲出节奏。':round.mode==='compose'?'把喜欢的声音排成一首歌。':'一拍一拍，认识不同的声音。' }}</h2></div><span>♫</span></div>
      <template v-if="round.mode==='follow'"><div class="music-score" aria-label="示范节奏"><span v-for="(instrument,index) in round.pattern" :key="index" :class="{current:current===index,hit:round.hits[index]}" :data-playing-note="current===index?index:undefined"><small>{{ index+1 }}</small><WorldSymbol :symbol="instruments[instrument].icon" /><b v-if="round.hits[index]">✓</b></span></div></template>
      <div v-else><div class="explore-toolbar" aria-label="编曲设置"><button v-for="size in [8,12,16]" :key="size" :aria-pressed="round.grid[0].length===size" :disabled="!!active" @click="length(size)">{{ size }} 拍</button><button v-for="(name,index) in ['行进鼓点','三拍摇摆','铃铛舞步']" :key="name" :disabled="!!active" @click="preset(index)">{{ name }}</button></div><div class="music-sequencer" aria-label="八拍编曲"><div v-for="(instrument,index) in instruments" :key="instrument.name"><span><WorldSymbol :symbol="instrument.icon" /><small>{{ instrument.name }}</small></span><button v-for="step in round.grid[0].length" :key="step" :data-sequence="`${index}-${step-1}`" :aria-label="`${instrument.name}第 ${step} 拍`" :aria-pressed="!!round.grid[index][step-1]" :class="{selected:round.grid[index][step-1],current:current===step-1}" :style="{background:round.grid[index][step-1]?instrument.color:undefined}" :disabled="!!active" @click="cell(index,step-1)">{{ step }}</button></div></div></div>
      <p v-if="round.mode==='compose'" class="explore-caption">共 {{ round.grid[0].length }} 拍，左右滑动节奏格查看后面的拍子。</p><div class="music-drums"><button v-for="(instrument,index) in instruments" :key="instrument.name" :aria-label="`敲击${instrument.name}`" :style="{borderColor:instrument.color}" @click="tap(index)"><span><WorldSymbol :symbol="instrument.icon" /></span><strong>{{ instrument.name }}</strong><small>键盘 {{ index+1 }}</small></button></div>
      <div class="music-buttons"><template v-if="!active"><button v-if="round.mode==='follow'" class="explore-secondary" @click="play('demo')">听一遍示范</button><button v-if="round.mode==='follow'" :disabled="round.finished" class="explore-primary" @click="play('follow')">跟着演奏</button><button v-else class="explore-primary" @click="play('compose')">播放我的节奏</button></template><button v-else class="explore-secondary" @click="stop">停止演奏</button></div>
      <p v-if="muted" class="explore-caption">暂时无法播放声音，可以跟着亮起的拍子演奏。</p><p class="explore-caption">{{ active?'先留一拍准备，再跟着亮起的节奏开始。':'从慢一点的速度开始，声音由浏览器直接合成。' }}</p>
    </div>
  </ExploreFrame>
</template>
<style scoped>
.music-sequencer{overflow-x:auto;padding:5px}.music-sequencer>div{display:flex!important;min-width:max-content}.music-sequencer>div>span{width:42px;flex-shrink:0}.music-sequencer button{width:36px;min-height:40px;flex-shrink:0}
.music-room:focus-visible{outline:2px dashed #b2c6a6;outline-offset:8px}.music-room label{display:flex;gap:8px;align-items:center;font-size:11px;color:#7a8e74;flex-wrap:wrap}.music-room input{width:90px;accent-color:#8da47b}.music-banner{display:flex;align-items:center;justify-content:center;gap:25px;padding:28px 15px;border-radius:17px;background:#e6e3f0;margin-bottom:26px;color:#8c7cab}.music-banner>span{font-size:50px;color:#b3a5c5}.music-banner small{font-size:11px}.music-banner h2{font-size:20px;font-weight:650;margin-top:7px}.music-score{display:flex;flex-wrap:wrap;justify-content:center;gap:9px;margin-bottom:27px}.music-score>span{position:relative;display:flex;align-items:center;justify-content:center;flex-direction:column;width:51px;height:70px;border:2px solid #d9e3d0;border-radius:12px;background:#fff;font-size:26px}.music-score small{font-size:10px;color:#9baa8f;margin-bottom:5px}.music-score .current{border-color:#c5a262;box-shadow:0 0 0 3px #e8d8b4}.music-score .hit{background:#e0edda}.music-score b{position:absolute;right:3px;top:2px;font-size:12px;color:#76a06e}.music-drums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin:24px 0}.music-drums button{display:flex;flex-direction:column;align-items:center;gap:9px;border:2px solid #d8c0ad;border-bottom-width:6px;background:white;border-radius:17px;padding:23px 4px;color:#78886f}.music-drums button:active{transform:translateY(3px);border-bottom-width:3px}.music-drums span{font-size:36px}.music-drums strong{font-size:13px;font-weight:600}.music-drums small{font-size:9px;color:#9aa68f}.music-buttons{display:flex;justify-content:center;gap:9px;flex-wrap:wrap}.music-sequencer>div{display:grid;grid-template-columns:52px repeat(8,minmax(0,1fr));gap:6px;margin-bottom:7px}.music-sequencer>div>span{font-size:24px;display:flex;align-items:center;flex-direction:column}.music-sequencer small{font-size:9px;color:#9a9b8e}.music-sequencer button{aspect-ratio:1;min-width:0;border:1px solid #d6e0cc;border-radius:7px;background:white;color:#9daba0;font-size:10px}.music-sequencer button.selected{color:white;border-color:#fff8}.music-sequencer button.current{outline:2px solid #b8a16d}@media(max-width:560px){.music-banner{gap:10px;padding:25px 10px}.music-banner h2{font-size:16px}.music-banner>span{font-size:30px}.music-drums{gap:7px}.music-drums button{padding:18px 3px}.music-drums span{font-size:30px}.music-drums strong{font-size:11px}.music-sequencer>div{grid-template-columns:32px repeat(8,minmax(0,1fr));gap:3px}.music-sequencer>div>span{font-size:19px}.music-sequencer small{font-size:8px}.music-score{gap:7px}.music-score>span{width:45px;height:64px}.music-room input{width:80px}}
</style>
